DROP TABLE IF EXISTS `batteries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `batteries` (
  `id` int NOT NULL AUTO_INCREMENT,
  `battery_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '电池编号',
  `battery_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '电池名称',
  `cabinet_id` int DEFAULT NULL COMMENT '所属电池柜ID',
  `park_id` int DEFAULT NULL COMMENT '所属园区ID',
  `location` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '安装位置',
  `manufacturer` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '制造商',
  `model` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '型号',
  `rated_capacity` decimal(10,4) DEFAULT NULL COMMENT '额定容量(Ah)',
  `rated_voltage` decimal(10,4) DEFAULT NULL COMMENT '额定电压(V)',
  `manufacture_date` date DEFAULT NULL COMMENT '生产日期',
  `install_date` date DEFAULT NULL COMMENT '安装日期',
  `status` enum('active','retired','testing','warning','danger') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `current_soh` decimal(10,4) DEFAULT NULL COMMENT '当前SOH值(%)',
  `current_rul` int DEFAULT NULL COMMENT '当前RUL值(次循环)',
  `current_pcl` decimal(10,4) DEFAULT NULL COMMENT '当前PCL值(%)',
  `total_cycles` int DEFAULT NULL COMMENT '总循环次数',
  `last_maintenance_date` date DEFAULT NULL COMMENT '最后维护日期',
  `dataset_type` enum('train','validation','test') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '数据集类型(仅实验室数据)',
  `is_lab_data` tinyint(1) NOT NULL COMMENT '是否为实验室数据(True:实验室124组, False:实际部署)',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '备注',
  `is_active` tinyint(1) NOT NULL COMMENT '是否激活',
  `created_at` datetime DEFAULT (now()) COMMENT '创建时间',
  `updated_at` datetime DEFAULT (now()) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `ix_batteries_battery_code` (`battery_code`) USING BTREE,
  KEY `ix_batteries_is_lab_data` (`is_lab_data`) USING BTREE,
  KEY `ix_batteries_park_id` (`park_id`) USING BTREE,
  KEY `ix_batteries_cabinet_id` (`cabinet_id`) USING BTREE,
  KEY `ix_batteries_is_active` (`is_active`) USING BTREE,
  KEY `ix_batteries_id` (`id`) USING BTREE,
  KEY `ix_batteries_status` (`status`) USING BTREE,
  KEY `ix_batteries_dataset_type` (`dataset_type`) USING BTREE,
  CONSTRAINT `batteries_ibfk_1` FOREIGN KEY (`cabinet_id`) REFERENCES `battery_cabinets` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT `batteries_ibfk_2` FOREIGN KEY (`park_id`) REFERENCES `parks` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=252 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

