--
-- Table structure for table `battery_lifecycle_data`
--

DROP TABLE IF EXISTS `battery_lifecycle_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `battery_lifecycle_data` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `battery_id` int NOT NULL COMMENT '电池组编号',
  `cycle_count` int NOT NULL COMMENT '循环次数',
  `voltage` decimal(10,4) NOT NULL COMMENT '电压(V)',
  `current` decimal(10,4) NOT NULL COMMENT '电流(A)',
  `temperature` decimal(10,4) NOT NULL COMMENT '温度(°C)',
  `capacity` decimal(10,4) NOT NULL COMMENT '容量(Ah)',
  `resistance` decimal(10,4) NOT NULL COMMENT '内阻(mΩ)',
  `soc` decimal(10,4) NOT NULL COMMENT 'SOC-荷电状态(%)',
  `soh` decimal(10,4) NOT NULL COMMENT 'SOH-健康状态(%)',
  `power` decimal(10,4) NOT NULL COMMENT '功率(W)',
  `rul` int NOT NULL COMMENT 'RUL-剩余使用寿命(循环次数)',
  `pcl` decimal(10,4) NOT NULL COMMENT 'PCL-容量衰减百分比(%)',
  `test_timestamp` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '测试时间',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_battery_cycle` (`battery_id`,`cycle_count`) USING BTREE,
  KEY `idx_battery_id` (`battery_id`) USING BTREE,
  KEY `idx_cycle_count` (`cycle_count`) USING BTREE,
  KEY `idx_rul` (`rul`) USING BTREE,
  KEY `idx_pcl` (`pcl`) USING BTREE,
  KEY `idx_soh` (`soh`) USING BTREE,
  KEY `idx_test_timestamp` (`test_timestamp`) USING BTREE,
  CONSTRAINT `battery_lifecycle_data_ibfk_1` FOREIGN KEY (`battery_id`) REFERENCES `batteries` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=10885 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='电池生命周期数据表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `battery_lifecycle_data`
--

LOCK TABLES `battery_lifecycle_data` WRITE;
