  `work_order_id` int DEFAULT NULL,
  `inspector` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `inspection_date` datetime NOT NULL,
  `status` enum('pending','in_progress','completed') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'completed',
  `result` enum('normal','abnormal','warning') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'normal',
  `soh_value` decimal(10,4) DEFAULT NULL,
  `temperature` decimal(10,4) DEFAULT NULL,
  `voltage` decimal(10,4) DEFAULT NULL,
  `current` decimal(10,4) DEFAULT NULL,
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `recommendations` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `battery_id` int DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否激活',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_module_id` (`module_id`) USING BTREE,
  KEY `idx_work_order_id` (`work_order_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_result` (`result`) USING BTREE,
  KEY `idx_inspection_records_is_active` (`is_active`) USING BTREE,
  CONSTRAINT `inspection_records_ibfk_1` FOREIGN KEY (`module_id`) REFERENCES `battery_modules` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `inspection_records_ibfk_2` FOREIGN KEY (`work_order_id`) REFERENCES `work_orders` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
