--
-- Table structure for table `models`
--

DROP TABLE IF EXISTS `models`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `models` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `algorithm_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '算法类型',
  `framework` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PyTorch' COMMENT '深度学习框架',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '模型描述',
  `hyperparameters` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '超参数 JSON字符串',
  `architecture` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '网络架构 JSON字符串',
  `input_shape` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '输入形状 JSON字符串',
  `output_shape` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '输出形状 JSON字符串',
  `metrics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '评估指标 JSON字符串',
  `trained_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '训练完成时间',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'completed' COMMENT '状态: pending, training, completed, failed',
  `model_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型文件路径',
  `checkpoint_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '检查点路径',
  `model_size` int DEFAULT NULL COMMENT '模型大小（字节）',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否激活',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_algorithm_type` (`algorithm_type`) USING BTREE,
  KEY `idx_framework` (`framework`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_is_active` (`is_active`) USING BTREE,
  KEY `idx_trained_at` (`trained_at`) USING BTREE,
  CONSTRAINT `models_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=78 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='模型表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `models`
--

LOCK TABLES `models` WRITE;
/*!40000 ALTER TABLE `models` DISABLE KEYS */;
