--
-- Table structure for table `prediction_records`
--

DROP TABLE IF EXISTS `prediction_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `prediction_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '预测记录ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `model_id` int NOT NULL COMMENT '模型ID',
  `battery_id` int NOT NULL COMMENT '电池ID',
  `input_data` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '输入数据 JSON字符串',
  `predicted_soh` float DEFAULT NULL COMMENT '预测SOH',
  `predicted_rul` float DEFAULT NULL COMMENT '预测RUL',
  `predicted_pcl` float DEFAULT NULL COMMENT '预测PCL（容量衰减）',
  `actual_soh` float DEFAULT NULL COMMENT '实际SOH（如果有）',
  `actual_rul` float DEFAULT NULL COMMENT '实际RUL（如果有）',
  `actual_pcl` float DEFAULT NULL COMMENT '实际PCL（容量衰减）',
  `prediction_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '预测时间',
  `execution_time` float DEFAULT NULL COMMENT '执行时间（毫秒）',
  `confidence` float DEFAULT NULL COMMENT '置信度',
  `error_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '误差分析 JSON字符串',
  `prediction_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'soh' COMMENT '预测类型: soh, rul, pcl, both',
  `notes` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `is_active` tinyint(1) DEFAULT '1' COMMENT '是否可用',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_model_id` (`model_id`) USING BTREE,
  KEY `idx_battery_id` (`battery_id`) USING BTREE,
  KEY `idx_prediction_type` (`prediction_type`) USING BTREE,
  KEY `idx_prediction_time` (`prediction_time`) USING BTREE,
  CONSTRAINT `prediction_records_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `prediction_records_ibfk_2` FOREIGN KEY (`model_id`) REFERENCES `models` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `prediction_records_ibfk_3` FOREIGN KEY (`battery_id`) REFERENCES `batteries` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=160 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='预测记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `prediction_records`
--

