--
-- Table structure for table `training_records`
--

DROP TABLE IF EXISTS `training_records`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `training_records` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '训练记录ID',
  `user_id` int NOT NULL COMMENT '用户ID',
  `model_id` int NOT NULL COMMENT '模型ID',
  `dataset_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据集路径',
  `training_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '训练配置 JSON字符串',
  `optimizer` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '优化器类型',
  `learning_rate` float DEFAULT NULL COMMENT '学习率',
  `batch_size` int DEFAULT NULL COMMENT '批次大小',
  `epochs` int DEFAULT NULL COMMENT '训练轮数',
  `start_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `end_time` timestamp NULL DEFAULT NULL COMMENT '结束时间',
  `duration` float DEFAULT NULL COMMENT '训练时长（秒）',
  `initial_loss` float DEFAULT NULL COMMENT '初始损失',
  `final_loss` float DEFAULT NULL COMMENT '最终损失',
  `best_val_loss` float DEFAULT NULL COMMENT '最佳验证损失',
  `convergence_epoch` int DEFAULT NULL COMMENT '收敛轮次',
  `train_metrics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '训练指标 JSON字符串',
  `validation_metrics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '验证指标 JSON字符串',
  `test_metrics` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '测试指标 JSON字符串',
  `parameters_count` int DEFAULT NULL COMMENT '参数数量',
  `memory_usage` float DEFAULT NULL COMMENT '内存使用量（MB）',
  `gpu_usage` float DEFAULT NULL COMMENT 'GPU使用率',
  `cpu_usage` float DEFAULT NULL COMMENT 'CPU使用率',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'running' COMMENT '状态: running, completed, failed',
  `logs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '训练日志',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_model_id` (`model_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_start_time` (`start_time`) USING BTREE,
  CONSTRAINT `training_records_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `training_records_ibfk_2` FOREIGN KEY (`model_id`) REFERENCES `models` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=75 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='训练记录表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `training_records`
--

LOCK TABLES `training_records` WRITE;
/*!40000 ALTER TABLE `training_records` DISABLE KEYS */;
