  `priority` enum('low','medium','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'medium' COMMENT '优先级',
  `status` enum('pending','assigned','in_progress','completed','cancelled','pending_review','rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending' COMMENT '工单状态',
  `issue_type` enum('soh_low','rul_warning','pcl_high','temperature_alert','voltage_abnormal','other') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'other' COMMENT '问题类型',
